<script setup>
import {ref,computed,onMounted,onUnmounted,inject} from 'vue';import {useRoute,useRouter} from 'vue-router';import {get,api} from '../api/client';import TableProposalWizard from './TableProposalWizard.vue';
import {Upload,Filter,Plus,X,ArrowUpDown,FileSpreadsheet,ChevronLeft,ChevronRight,Download,RotateCcw} from 'lucide-vue-next';
const route=useRoute(),router=useRouter(),user=inject('user');const wizard=ref(false),analysisJob=ref(null);async function analyze(){try{const r=await api('/analysis-runs',{method:'POST',body:{document_revision_id:workbook.value.document_revision_id,workflow_profile:'price_table'}});router.push('/jobs/'+r.data.id)}catch(e){error.value=e.message}}const canReview=computed(()=>user.value.roles.some(r=>['admin','reviewer'].includes(r)));const workbooks=ref([]),workbook=ref(null),sheetId=ref(''),rows=ref({items:[],total:0}),error=ref(''),loading=ref(false),uploading=ref(false),file=ref(null),search=ref(''),filters=ref([]),sort=ref('row_number'),direction=ref('asc'),offset=ref(0),limit=ref(50),detail=ref(null),hidden=ref([]);let controller,serial=0,disposed=false;
const canUpload=computed(()=>user.value.roles.some(r=>['admin','operator'].includes(r)));const sheet=computed(()=>workbook.value?.sheets.find(s=>s.id===sheetId.value));const columns=computed(()=>(sheet.value?.columns||[]).filter(c=>!hidden.value.includes(c.key)));const validFilters=computed(()=>filters.value.filter(f=>['empty','not_empty'].includes(f.op)||f.value!==''));
async function list(){const data=await get('/price-workbooks');workbooks.value=data.items;return data.items}
async function openWorkbook(id){error.value='';try{workbook.value=await get('/price-workbooks/'+id);sheetId.value=workbook.value.sheets[0]?.id||'';reset(false);if(sheetId.value)await load();else rows.value={items:[],total:0};router.replace({query:{...route.query,workbook:id}})}catch(e){error.value=e.message}}
onMounted(async()=>{try{const items=await list();const initial=items.find(x=>x.id===route.query.workbook)||items[0];if(initial)await openWorkbook(initial.id)}catch(e){error.value=e.message}});onUnmounted(()=>{disposed=true;controller?.abort()});
function reset(fetch=true){filters.value=[];search.value='';sort.value='row_number';direction.value='asc';offset.value=0;hidden.value=[];detail.value=null;if(fetch)load()}
function switchSheet(id){sheetId.value=id;reset();}
async function load(resetPage=false){if(!sheetId.value||disposed)return;if(resetPage)offset.value=0;controller?.abort();controller=new AbortController();const seq=++serial;loading.value=true;error.value='';detail.value=null;
 try{const q=new URLSearchParams({q:search.value,filters:JSON.stringify(validFilters.value),sort:sort.value,direction:direction.value,offset:String(offset.value),limit:String(limit.value)});const r=await api('/price-sheets/'+sheetId.value+'/rows?'+q,{signal:controller.signal});if(!disposed&&seq===serial)rows.value=r.data}catch(e){if(e.name!=='AbortError'&&seq===serial)error.value=e.message}finally{if(seq===serial)loading.value=false}}
function addFilter(){filters.value.push({id:crypto.randomUUID(),column:sheet.value.columns[1]?.key||sheet.value.columns[0].key,op:'contains',value:''})}
function setColumn(f){f.op='contains';f.value=''}
function numeric(f){return sheet.value?.columns.find(c=>c.key===f.column)?.numeric}
function sortBy(c){if(sort.value===c.key)direction.value=direction.value==='asc'?'desc':'asc';else{sort.value=c.key;direction.value='asc'}load(true)}
function cellValue(row,col){const v=row.cells[col.key];if(v===undefined||v===null||v==='')return '—';if(col.numeric){const parts=String(v).split('.');return parts[0].replace(/\B(?=(\d{3})+(?!\d))/g,',')+(parts.length>1?'.'+parts[1]:'')}return String(v)}
async function upload(){if(!file.value)return;uploading.value=true;error.value='';try{const form=new FormData();form.append('file',file.value);form.append('title',file.value.name);const r=await api('/price-workbooks/import',{method:'POST',body:form});await list();await openWorkbook(r.data.id);analysisJob.value=r.data.analysis_job?.id;file.value=null}catch(e){error.value=e.message}finally{uploading.value=false}}
async function headerChanged(value){error.value='';try{const r=await api('/price-sheets/'+sheetId.value+'/header',{method:'POST',body:{header_row:Number(value)}});workbook.value=r.data;reset()}catch(e){error.value=e.message}}async function original(){try{const rev=await get('/document-revisions/'+workbook.value.document_revision_id);const a=await get('/assets/'+rev.snapshot_asset_id+'/access');window.open(a.url,'_blank','noopener')}catch(e){error.value=e.message}}
function changePage(delta){offset.value=Math.max(0,offset.value+delta*limit.value);load()}
</script>
<template><div class="page-heading"><div><div class="eyebrow">IMPORTED MATERIALS</div><h1>가져온 표 검토</h1><p class="muted">엑셀의 시트와 열을 유지한 채 조회하고, 여러 열의 조건을 함께 적용하세요.</p></div><div class="row"><button v-if="workbook&&canUpload" class="primary" @click="analyze">AI로 추출·엑셀 만들기 →</button><button v-if="workbook&&canReview" class="secondary" @click="wizard=true">열 직접 연결</button><button v-if="workbook" class="secondary" @click="original"><Download :size="15"/> 원본 다운로드</button></div></div><div v-if="canUpload" class="workbook-upload"><FileSpreadsheet :size="22"/><div class="grow"><strong>단가표 파일 가져오기</strong><p class="muted small">XLSX · 최대 20MB · 열 제목 행은 자동 제안하며 직접 지정할 수 있습니다. 승인된 상품 DB는 변경되지 않습니다.</p></div><input type="file" accept=".xlsx" aria-label="단가표 파일 선택" @change="file=$event.target.files[0]" :disabled="uploading"><button class="primary" :disabled="!file||uploading" @click="upload"><Upload :size="15"/>{{uploading?'표를 가져오는 중…':'표 가져오기'}}</button></div><p v-if="analysisJob" class="notice">AI 분석을 자동으로 시작했습니다. <RouterLink :to="'/jobs/'+analysisJob">추출 결과·검토용 엑셀 보기 →</RouterLink></p><p v-if="error" class="error" role="alert">{{error}}</p><template v-if="workbook"><section class="panel sheet-panel"><div class="workbook-heading"><label>등록 파일<select :value="workbook.id" @change="openWorkbook($event.target.value)" aria-label="등록 파일"><option v-for="w in workbooks" :value="w.id">{{w.filename}}</option></select></label><RouterLink :to="'/documents/'+workbook.document_id" class="small">원문·검토 문서 보기 ↗</RouterLink></div><div class="sheet-tabs" role="tablist" aria-label="엑셀 시트"><button v-for="s in workbook.sheets" :key="s.id" role="tab" :aria-selected="sheetId===s.id" :class="{active:sheetId===s.id}" @click="switchSheet(s.id)"><FileSpreadsheet :size="14"/>{{s.name}}<span>{{s.row_count.toLocaleString()}}행</span></button></div><div class="sheet-tools"><form class="row" @submit.prevent="load(true)"><input v-model="search" placeholder="모든 열에서 검색" aria-label="전체 열 검색"><button class="secondary" :disabled="loading">검색</button></form><div class="row wrap"><button class="secondary" @click="addFilter"><Plus :size="15"/> 열 필터 추가</button><button class="quiet small" @click="reset()"><RotateCcw :size="13"/> 초기화</button><details class="column-menu"><summary>표시할 열 {{columns.length}} / {{sheet?.columns.length}}</summary><div><label v-for="c in sheet?.columns" :key="c.key"><input type="checkbox" :checked="!hidden.includes(c.key)" @change="$event.target.checked?hidden=hidden.filter(x=>x!==c.key):hidden.push(c.key)">{{c.label}}</label></div></details></div></div><form v-if="filters.length" class="column-filters" @submit.prevent="load(true)"><div class="small muted"><Filter :size="13"/> 모든 조건을 함께 만족하는 행을 조회합니다.</div><div v-for="(f,index) in filters" :key="f.id" class="filter-row"><span class="filter-and">{{index?'그리고':'조건'}}</span><select v-model="f.column" :aria-label="'필터 열 '+(index+1)" @change="setColumn(f)"><option v-for="c in sheet.columns" :value="c.key">{{c.label}}</option></select><select v-model="f.op" :aria-label="'필터 조건 '+(index+1)"><option value="contains">포함</option><option value="equals">정확히 일치</option><template v-if="numeric(f)"><option value="gte">이상 (≥)</option><option value="lte">이하 (≤)</option><option value="eq_number">숫자 일치 (=)</option></template><option value="empty">비어 있음</option><option value="not_empty">비어 있지 않음</option></select><input v-if="!['empty','not_empty'].includes(f.op)" v-model="f.value" :inputmode="['gte','lte','eq_number'].includes(f.op)?'decimal':'text'" :aria-label="'필터 값 '+(index+1)" placeholder="조건 값"><span v-else class="grow"></span><button type="button" class="icon-button" :aria-label="'필터 삭제 '+(index+1)" @click="filters.splice(index,1)"><X :size="17"/></button></div><button class="primary small" :disabled="loading">필터 적용</button></form><div class="sheet-status"><label class="inline-label">열 제목 행 <input type="number" min="1" max="20000" :value="sheet?.header_row" @change="headerChanged($event.target.value)" :disabled="!canUpload&&!canReview" aria-label="열 제목 행 번호" style="width:65px;padding:5px">행</label><span aria-live="polite">{{loading?'조회 중…':`${rows.total.toLocaleString()}행 조회`}} <span class="muted">/ 전체 {{sheet?.row_count.toLocaleString()}}행</span></span><div class="row"><span class="small muted">열 제목을 누르면 정렬 · 행을 누르면 상세</span><label class="inline-label">페이지당 <select v-model="limit" @change="load(true)"><option :value="25">25행</option><option :value="50">50행</option><option :value="100">100행</option></select></label></div></div><div class="spreadsheet-scroll" :class="{loading}" :aria-busy="loading"><table class="spreadsheet-table"><thead><tr><th class="row-number">행</th><th v-for="c in columns" :key="c.key" :class="{number:c.numeric}" :aria-sort="sort===c.key?(direction==='asc'?'ascending':'descending'):'none'"><button @click="sortBy(c)" :aria-label="c.label+' 정렬'"><span><small>{{c.key}}</small>{{c.label}}</span><span class="sort-arrow">{{sort===c.key?(direction==='asc'?'↑':'↓'):'↕'}}</span></button></th></tr></thead><tbody><tr v-for="row in rows.items" :key="row.row_number" @click="detail=row" tabindex="0" @keydown.enter="detail=row" :aria-label="'원본 '+row.row_number+'행 상세'"><th class="row-number">{{row.row_number}}</th><td v-for="c in columns" :key="c.key" :class="{number:c.numeric,blank:row.cells[c.key]===undefined}" :title="row.cells[c.key]??'빈 셀'"><span>{{cellValue(row,c)}}</span></td></tr></tbody></table><div v-if="!loading&&!rows.items.length" class="empty">조건에 맞는 행이 없습니다. 검색어나 필터를 조정하세요.</div></div><div class="sheet-pagination"><span class="small muted">{{rows.total?offset+1:0}}–{{Math.min(offset+limit,rows.total)}} / {{rows.total.toLocaleString()}}행</span><div class="row"><button class="secondary" :disabled="loading||offset===0" @click="changePage(-1)"><ChevronLeft :size="15"/> 이전</button><button class="secondary" :disabled="loading||!rows.has_more" @click="changePage(1)">다음 <ChevronRight :size="15"/></button></div></div></section><div class="notice">원본에 입력된 값과 메모를 그대로 표시합니다. 0은 빈 값과 다르며, ‘조사가’를 ‘적용가’로 자동 대체하지 않습니다. 수식은 파일에 저장된 계산 결과를 표시합니다.</div></template><section v-else-if="!error" class="panel empty">등록된 표 자료가 없습니다. 자료 관리에서 파일을 가져와 주세요.</section><TableProposalWizard v-if="wizard&&sheet" :sheet="sheet" :workbook="workbook" @close="wizard=false"/><div v-if="detail" class="modal-backdrop" @click.self="detail=null"><section class="modal cell-detail"><button class="close" @click="detail=null" aria-label="행 상세 닫기">×</button><div class="eyebrow">ORIGINAL ROW REFERENCE</div><h2>{{sheet.name}} · {{detail.row_number}}행</h2><p class="muted small">{{workbook.filename}} · {{detail.cell_range}}</p><dl><div v-for="c in sheet.columns" :key="c.key"><dt><small>{{c.key}}{{detail.row_number}}</small>{{c.label}}</dt><dd>{{cellValue(detail,c)}}</dd></div></dl><button class="secondary" @click="original">원본 파일 다운로드</button></section></div></template>
